<?php
declare(strict_types=1);require_once __DIR__.'/../app/bootstrap.php';$u=require_auth();$st=db()->prepare('SELECT er.*,r.name region_name,d.name district_name,w.name ward_name FROM expert_requests er JOIN locations_regions r ON r.code=er.region_code JOIN locations_districts d ON d.region_code=er.region_code AND d.code=er.district_code JOIN locations_wards w ON w.region_code=er.region_code AND w.district_code=er.district_code AND w.code=er.ward_code WHERE er.buyer_user_id=? ORDER BY er.id DESC');$st->execute([(int)$u['id']]);$rows=$st->fetchAll();ob_start(); ?>
<div class="card pad reveal"><div style="display:flex;justify-content:space-between;gap:1rem;flex-wrap:wrap"><div><div class="kicker">My requests</div><h1>Expert requests</h1></div><a class="btn" href="<?= APP_BASE_URL ?>/expert-request.php">New request</a></div><?php if(!$rows):?><p class="sub">You have not requested an expert yet.</p><?php else:?><div class="request-grid"><?php foreach($rows as $row):?><article class="request-card"><div><span class="pill <?= $row['status']==='assigned'?'ok':'warn' ?>"><?= h((string)$row['status']) ?></span></div><h3><?= h(ucwords(str_replace('_',' ',(string)$row['expert_type']))) ?></h3><p class="sub"><?= h((string)$row['region_name']) ?> · <?= h((string)$row['district_name']) ?> · <?= h((string)$row['ward_name']) ?></p><p><?= nl2br(h((string)$row['description'])) ?></p><?php if($row['admin_notes']):?><div class="instr-note"><strong>Admin update:</strong> <?= nl2br(h((string)$row['admin_notes'])) ?></div><?php endif;?></article><?php endforeach;?></div><?php endif;?></div>
<?php $content=ob_get_clean();$title='My expert requests. Ardhi Way';require __DIR__.'/_layout.php';
